from common import *

def room():
    c1 = calc('c1', "Why a metal is only weakly magnetic: Pauli versus Curie", 'normal',
      "Script 6.2: sodium, $n=2.65\\times10^{28}$ m$^{-3}$ (one electron per atom), $g=2$. Free electron gas: $\\epsilon_F=\\hbar^2(3\\pi^2n)^{2/3}/2m$, $\\nu(\\epsilon_F)=3n/2\\epsilon_F$. Pauli susceptibility $\\chi_P=\\mu_0\\frac{(g\\mu_B)^2}{4}\\nu(\\epsilon_F)$. For comparison, the same number of **localised** $S=\\frac12$ moments would obey Curie, $\\chi=C/T$ with $C=\\mu_0\\frac{(g\\mu_B)^2S(S+1)}{3k_BV_0}$, $V_0=1/n$. Room temperature $T=300$ K.",
      V('kB', 'mu0', 'muB', n=2.65e28, g=2.0, T=300.0),
      [step('EF', "Fermi energy in eV.", "hbar**2*(3*pi**2*n)**(2/3)/(2*me)/eV", "eV", ["eV", "meV", "K", "A^-1"], 0.02,
            "$\\hbar^2(3\\pi^2n)^{2/3}/2m=3.24$ eV for Na."),
       step('nu', "Density of states at the Fermi energy $\\nu(\\epsilon_F)=3n/(2\\epsilon_F)$ in J$^{-1}$m$^{-3}$.", "3*n/(2*EF*eV)", "J^-1 m^-3", ["J^-1 m^-3", "J m^-3", "eV^-1", "m^-3"], 0.02,
            "Both spin directions included. Each spin species has $\\nu/2$."),
       step('chiP', "Pauli susceptibility $\\chi_P$ (dimensionless, SI).", "mu0*(g*muB)**2/4*nu", "dimensionless", ["dimensionless", "K", "A/m", "J/T"], 0.03,
            "Only the electrons in a shell $\\sim\\nu k_BT$ at $\\epsilon_F$ can flip their spin, each contributing $\\propto1/k_BT$: the $T$ cancels (script 6.12-6.16). $\\chi_P\\approx8\\times10^{-6}$: weak, positive, temperature independent."),
       step('chiC', "Curie susceptibility the same number of free $S=\\frac12$ moments would have at 300 K, $\\mu_0(g\\mu_B)^2n/(4k_BT)$.", "mu0*(g*muB)**2*n/(4*kB*T)", "dimensionless", ["dimensionless", "K", "A/m", "J/T"], 0.03,
            "$S(S+1)/3=\\frac14$ for $S=\\frac12$. Result $\\approx7\\times10^{-4}$."),
       step('ratio', "Ratio $\\chi_{\\rm Curie}/\\chi_P$.", "chiC/chiP", "dimensionless", ["dimensionless", "K", "eV", "J/T"], 0.03,
            "Exactly $2\\epsilon_F/(3k_BT)\\approx83$: the Pauli principle suppresses the susceptibility by $T/T_F$. Landau diamagnetism adds $\\chi_L=-\\chi_P/3$ (script 6.17), so a free-electron metal is still paramagnetic.")],
      60)

    c2 = calc('c2', "Weiss temperature on a lattice with two couplings", 'normal',
      "Zheludev, Jan 2024, Problem 4 / Aug 2024, Problem 4, with numbers. **Convention of this script (6.63):** $H=-\\sum_{\\{i,j\\}}J_{ij}\\,\\vec S_i\\cdot\\vec S_j$ over each bond once, so $J>0$ is ferromagnetic and $k_BT_W=J_{\\rm total}\\,S(S+1)/3$ with $J_{\\rm total}=\\sum_jJ_{ij}$ over all neighbours of one spin (6.60-6.65). The exam sheets use the opposite sign ($H=+\\sum J\\,\\vec S\\cdot\\vec S$, $J>0$ antiferromagnetic) and write $T_W=-J_{\\rm total}S(S+1)/3k_B$; **always read the sign convention off the problem.** Spins $S=1$. The brick-wall (honeycomb) lattice has per site one ferromagnetic $J_1=+2.0$ meV bond and two antiferromagnetic $J_2=-1.5$ meV bonds. The triangular lattice has per site two $J_1$ and four $J_2$ bonds.",
      V('kB', S=1.0, J1=2.0, J2=-1.5),
      [step('Jtot', "$J_{\\rm total}=J_1+2J_2$ for the honeycomb lattice, in meV.", "J1+2*J2", "meV", ["meV", "K", "eV", "T"], 0.02,
            "Sum over all neighbours of one spin: one $J_1$ bond and two $J_2$ bonds. Negative: net antiferromagnetic."),
       step('TW', "Weiss temperature $T_W=J_{\\rm total}S(S+1)/(3k_B)$ in K (keep the sign).", "Jtot*1e-3*eV*S*(S+1)/(3*kB)", "K", ["K", "meV", "eV", "T"], 0.03,
            "$-1.0\\,{\\rm meV}\\times2/3=-0.67$ meV $=-7.7$ K. The Curie–Weiss law $\\chi=C/(T-T_W)$ extrapolates to a negative intercept: antiferromagnetic correlations although the $J_1$ dimers are ferromagnetic."),
       step('TWtri', "Triangular lattice with the same $J_1,J_2$: $T_W$ in K.", "(2*J1+4*J2)*1e-3*eV*S*(S+1)/(3*kB)", "K", ["K", "meV", "eV", "T"], 0.03,
            "$J_{\\rm total}=2J_1+4J_2=-2$ meV, exactly twice the honeycomb result because there are twice as many neighbours with the same ratio $J_1:J_2$."),
       step('chi', "Curie–Weiss at $T=50$ K: susceptibility relative to non-interacting spins, $\\chi/\\chi_0=T/(T-T_W)$.", "50/(50-TW)", "dimensionless", ["dimensionless", "K", "T", "meV"], 0.02,
            "$\\chi=C/(T-T_W)$ with $T_W<0$ lowers $\\chi$ below the free-spin Curie value $C/T$ (antiferromagnetic correlations). A ferromagnet ($T_W>0$) would enhance it and diverge at $T_W$. In the ordered state the ground state here is an antiferromagnet of ferromagnetic dimers: the Néel arrangement of dimers satisfies every bond (any common rotation of all spins is also a ground state).")],
      60)

    c3 = calc('c3', "At what field is the antiferromagnet saturated?", 'normal',
      "Same lattices, $S=1$, $g=2$, $J_2=-1.5$ meV (antiferromagnetic in this script's sign convention; $|J_2|=1.5$ meV). Apply a field $\\mu_0H\\perp$ the Néel axis at $T=0$. In the canted state the sublattice spins tilt by an angle $\\theta$ towards the field; the energy per spin is $E(\\theta)=\\text{const}-\\tfrac12J_{\\rm AF}S^2\\cos2\\theta-g\\mu_B\\mu_0HS\\sin\\theta$, where $J_{\\rm AF}=\\sum|J|$ runs over the antiferromagnetic neighbours of one spin (each bond is shared by two spins, hence the $\\frac12$) and the ferromagnetic bonds are unaffected by the canting. Minimising gives $g\\mu_B\\mu_0H=2J_{\\rm AF}S\\sin\\theta$, saturation at $\\theta=\\pi/2$.",
      V('muB', 'e', S=1.0, g=2.0, J2=1.5),
      [step('JAFh', "$J_{\\rm AF}$ for the honeycomb lattice (two antiferromagnetic $J_2$ neighbours per spin), in meV.", "2*J2", "meV", ["meV", "K", "T", "eV"], 0.02,
            "Number of antiferromagnetic neighbours $\\times|J_2|$. (Script 6.74: $J_{\\rm total}=JZ$.)"),
       step('Hh', "Saturation field $\\mu_0H_{\\rm sat}=2J_{\\rm AF}S/(g\\mu_B)$ for the honeycomb lattice in tesla.", "2*JAFh*1e-3*e*S/(g*muB)", "T", ["T", "A/m", "meV", "K"], 0.03,
            "$2\\times3.0\\,{\\rm meV}\\times1/(2\\times0.0579\\,{\\rm meV/T})=51.8$ T. Check from the script: $H=2\\frac{J_{\\rm total}}{(g\\mu_B)^2\\mu_0}2V_0|M_1|\\sin\\alpha$ with $|M_1|=g\\mu_BS/2V_0$ (6.73-6.78): same. **The printed exam keys give twice this** ($8J_2S/g\\mu_B\\mu_0$ for honeycomb, $16J_2S$ for the triangular lattice): they count every bond fully in the energy per spin (ordered pairs) while their $T_W$ counts each bond once; with the script's convention the factor is as above. Test: two $S=\\frac12$ spins with one bond $J$: singlet and $m=1$ triplet cross at $g\\mu_B\\mu_0H=J$, which the formula reproduces ($2\\cdot1\\cdot J\\cdot\\frac12$)."),
       step('Ht', "Triangular lattice (four antiferromagnetic $J_2$ neighbours): saturation field in tesla.", "2*(4*J2)*1e-3*e*S/(g*muB)", "T", ["T", "A/m", "meV", "K"], 0.03,
            "$J_{\\rm AF}=4|J_2|=6$ meV: twice the honeycomb value. The $J_1$ rows stay ferromagnetic throughout."),
       step('dimer', "Check on the quantum limit: two spins $S=\\frac12$, one bond $|J|=1$ meV, $g=2$. Field at which the singlet–triplet crossing happens, in tesla.", "1e-3*e/(g*muB)", "T", ["T", "A/m", "meV", "K"], 0.03,
            "Crossing at $g\\mu_B\\mu_0H=|J|$: $8.64$ T. This is exactly $2ZJS/g\\mu_B$ with $Z=1,S=\\frac12$, and it fixes the factor of 2 beyond doubt.", bonus=True)],
      70)

    c4 = calc('c4', "Exchange versus dipoles: how strong is iron's exchange?", 'fermi',
      "Quick fight. Iron is ferromagnetic up to $T_C=1043$ K (bcc, $Z=8$ nearest neighbours, take $S=1$). Mean field: $k_BT_C=|J|Z\\,S(S+1)/3$ (script 6.72). Script 6.2.5: the magnetic dipolar interaction between neighbouring electrons is only $\\sim0.1$ meV ($\\sim1$ K). Estimate $|J|$ in meV (within a factor of 1.3) and compare.",
      V('kB', TC=1043.0, Z=8.0, S=1.0, Edip=0.1),
      [step('J', "Exchange constant $|J|=3k_BT_C/[Z\\,S(S+1)]$ in meV.", "3*kB*TC/(Z*S*(S+1))/eV*1e3", "meV", ["meV", "eV", "K", "T"], 0.1,
            "$3\\times0.0862\\,{\\rm meV/K}\\times1043/(8\\times2)=16.9$ meV. Mean field overestimates $T_C$ a little, so the true $J$ is somewhat larger.", tolType='log'),
       step('ratio', "How many times stronger than the dipolar energy is it, $|J|/E_{\\rm dip}$?", "J/Edip", "dimensionless", ["dimensionless", "K", "meV", "T"], 0.1,
            "A factor $\\sim170$: dipoles would give $T_C\\sim6$ K, not 1043 K. The effective spin–spin interaction comes from Coulomb repulsion plus the Pauli principle (script 6.3.1), not from magnetism at all.", tolType='log')],
      20)

    SRC = dict(file="materials/solid-state/old-exams/HS23 (1).pdf", where="Problem 4 'Magnetism' (Zheludev, 16 Aug 2024); solution: solutions/Einführung in die Festkörperphysik HS23 (Solution).pdf, Problem 4")
    boss1 = boss('b1', "Boss: magnetism on a triangular lattice (exam problem)", SRC, 30,
      "Statement and signs are the exam's: **here $J>0$ is antiferromagnetic** ($H=+\\sum J\\vec S_i\\cdot\\vec S_j$). Solve on paper under the timer, then enter the game numbers. Pay attention to the factor in (f): compare with your own derivation.",
      ["Consider the following lattice of magnetic atoms of spin $S$ (a triangular lattice, drawn with horizontal rows). The magnetic atoms are coupled by Heisenberg couplings $J_1\\ne J_2$: $J_1$ (solid line) along the rows, $J_2$ (dashed) along the two diagonals. Each spin has 2 neighbours at $J_1$ and 4 at $J_2$. First both couplings are ferromagnetic, $J_1,J_2<0$.",
       "(a) [0.5 pt] Draw a ground-state spin configuration.  (b) [0.5 pt] Is there another ground state? If so, draw it.  (c) [0.5 pt] Find the Weiss temperature.",
       "Now for the same lattice $J_1<0$ and $J_2>0$.",
       "(d) [0.5 pt] Draw a ground-state spin configuration.  (e) [0.5 pt] Find the Weiss temperature.  (f) [0.5 pt] A field $H\\perp\\vec S$ is applied perpendicular to the spin direction of (d). At what magnitude of $H$ is the moment saturated? Assume $T=0$.",
       "Game numbers: $S=3/2$, $g=2$; for (c) $J_1=-0.40$ meV, $J_2=-0.20$ meV; for (d)-(f) $J_1=-0.40$ meV, $J_2=+0.50$ meV."],
      [fa('TWc', "(c) Weiss temperature in K, $T_W=-(2J_1+4J_2)S(S+1)/3k_B$ with $J_1=-0.40$, $J_2=-0.20$ meV.", "-(2*J1+4*J2)*1e-3*eV*S*(S+1)/(3*kB)", dict(kB=K['kB'], S=1.5, J1=-0.40, J2=-0.20), 0.03),
       fa('TWe', "(e) Weiss temperature in K for $J_1=-0.40$, $J_2=+0.50$ meV (keep the sign).", "-(2*J1+4*J2)*1e-3*eV*S*(S+1)/(3*kB)", dict(kB=K['kB'], S=1.5, J1=-0.40, J2=0.50), 0.03),
       fa('E0', "(d) Classical ground-state energy per spin in meV: $J_1S^2-2J_2S^2$ for the ferromagnetic rows, antiparallel between rows.", "J1*S**2-2*J2*S**2", dict(S=1.5, J1=-0.40, J2=0.50), 0.03),
       fa('Hsat', "(f) Saturation field $\\mu_0H_{\\rm sat}=2\\cdot(4J_2)S/(g\\mu_B)$ in tesla (derive it; compare with the printed key).", "2*(4*J2)*1e-3*e*S/(g*muB)", dict(e=K['e'], muB=K['muB'], g=2.0, S=1.5, J2=0.50), 0.03)],
      ["(a) Ferromagnetic ground state: all spins parallel (any common direction; all bonds satisfied).",
       "(b) Any rotation of the common direction; no other (collinear) state with all bonds satisfied.",
       "(c) $T_W=-\\sum_{\\rm neighbours}J\\,\\dfrac{S(S+1)}{3k_B}=-(2J_1+4J_2)\\dfrac{S(S+1)}{3k_B}$ (exam sign convention $H=+J\\vec S\\cdot\\vec S$; the script's $-J$ convention gives $+J_{\\rm total}S(S+1)/3k_B$). Positive for $J_1,J_2<0$.",
       "(d) Ferromagnetic rows ($J_1<0$), antiparallel between neighbouring rows ($J_2>0$): each spin has two neighbours in the row above and two below, all antiparallel, so all bonds are satisfied.",
       "(e) Same formula: $T_W=-(2J_1+4J_2)S(S+1)/3k_B$.",
       "(f) Canted energy per spin: $E(\\theta)=J_1S^2-2J_2S^2\\cos2\\theta-g\\mu_B\\mu_0HS\\sin\\theta$ (each of the 4 antiferromagnetic bonds counted with weight $\\frac12$). $\\partial E/\\partial\\theta=0$: $8J_2S\\sin\\theta=g\\mu_B\\mu_0H$; saturated at $\\theta=\\pi/2$: $\\mu_0H_{\\rm sat}=8J_2S/(g\\mu_B)$. The printed key writes $E=2J_1S^2+4J_2S^2\\cos(\\pi-2\\theta)-\\ldots$ (every bond with weight 1) and finds $16J_2S/(g\\mu_B\\mu_0)$; with the same bond convention as its $T_W$ (each bond once) the result is $8J_2S/(g\\mu_B\\mu_0)$, confirmed by the two-spin singlet–triplet check $g\\mu_B\\mu_0H=J$. State your convention in the exam and keep it consistent between (c)/(e) and (f).",
       "(f) Alternative route (script 6.78): $H=2\\frac{J_{\\rm total}}{(g\\mu_B)^2\\mu_0}2V_0|M_1|\\sin\\alpha$ with $J_{\\rm total}\\to4J_2$ and $|M_1|=g\\mu_BS/2V_0$ (the sublattice magnetisation is normalised to the full volume, script 6.73)."],
      100)

    return dict(file='magnet-vault', id='ss-magnet-vault', region="Solid State Crystal Caverns", title="The Magnet Vault", course="solid-state",
      topics=["Pauli paramagnetism, Landau diamagnetism", "Curie law, exchange interaction J", "Weiss field, Curie-Weiss, T_W and T_C", "antiferromagnet, Néel state, saturation field", "Stoner criterion"],
      sources=[dict(file="materials/solid-state/old-exams/HS23.pdf", where="Problem 4 'Honeycomb lattice' (Zheludev, Jan 2024); solution (1), Problem 4"),
               dict(file="materials/solid-state/old-exams/HS23 (1).pdf", where="Problem 4 (Aug 2024, triangular lattice); solution HS23 (Solution).pdf"),
               dict(file="materials/solid-state/old-exams/HS20.pdf", where="MC (r) sign of the exchange energy J"),
               dict(file="materials/solid-state/scripts/Script-2026_2026-09-01.pdf", where="Ch. 6.1-6.3 (pp. 136–161): Pauli, Landau, Hubbard/Stoner, exchange, mean field, Curie-Weiss, ferro- and antiferromagnets"),
               dict(file="notes/solid-state/04-semiconductors-and-magnetism.md", where="transcription, formulas, convention warnings")],
      links=[dict(course="qm", room="stern-gerlach", why="Zeeman splitting $\\mp\\frac12g\\mu_B\\mu_0H$ of a spin-$\\frac12$, the spin-$S$ sum giving $S(S+1)$, and the singlet/triplet spectrum of two spins (QM sheets 11-14)."),
             dict(course="astro", room="photometry-radiation", why="Zeeman splitting and 21 cm hyperfine line (spin flips) are the astronomical use of the same spin physics.")],
      intro="The vault holds spins. A metal answers a field weakly (Pauli), localised moments answer strongly (Curie), and exchange turns paramagnets into ferro- or antiferromagnets. Compute Weiss temperatures and the field that tips a Néel state to saturation, and watch the sign conventions.",
      encounters=[c1, c2, c3, c4, boss1])
